SessionStartupPref GetSessionStartupPref(const base::CommandLine& command_line, Profile* profile) {
  SessionStartupPref pref;

  if (!profile)
    return SessionStartupPref(SessionStartupPref::DEFAULT);

  PrefService* prefs = profile->GetPrefs();
  if (!prefs)
    return SessionStartupPref(SessionStartupPref::DEFAULT);

  // Check if it's the first run or restart after update.
  if (command_line.HasSwitch(switches::kFirstRun) || command_line.HasSwitch(switches::kRestart)) {
    pref.type = SessionStartupPref::DEFAULT;
    return pref;
  }

  // Handle guest sessions or incognito mode.
  if (profile->IsGuestSession() || profile->IsOffTheRecord()) {
    pref.type = SessionStartupPref::LAST;
    return pref;
  }

  // Otherwise, load the user's saved session preferences.
  pref.type = static_cast<SessionStartupPref::Type>(prefs->GetInteger(prefs::kSessionStartupType));
  if (pref.type == SessionStartupPref::INVALID) {
    pref.type = SessionStartupPref::DEFAULT;
  }

  return pref;
}

