SessionStartupPref GetStartupPref(const base::CommandLine& command_line, Profile* profile) {
  SessionStartupPref pref;

  if (!profile || profile->IsOffTheRecord()) {
    pref.type = SessionStartupPref::LAST;
    return pref;
  }

  if (command_line.HasSwitch(switches::kRestoreLastSession)) {
    pref.type = SessionStartupPref::LAST;
  } else if (command_line.HasSwitch(switches::kNewTab)) {
    pref.type = SessionStartupPref::NEW_TAB;
  } else if (command_line.HasSwitch(switches::kURL)) {
    pref.type = SessionStartupPref::URLS;
    const std::vector<std::string>& urls = command_line.GetSwitchValueAsList(switches::kURL);
    pref.urls.assign(urls.begin(), urls.end());
  } else {
    PrefService* prefs = profile->GetPrefs();
    pref.type = static_cast<SessionStartupPref::Type>(prefs->GetInteger(prefs::kSessionStartupPref));

    if (pref.type == SessionStartupPref::DEFAULT) {
      pref.type = SessionStartupPref::LAST;
    }

    if (profile->IsGuestSession() || profile->IsSystemProfile()) {
      pref.type = SessionStartupPref::URLS;
      pref.urls.push_back("chrome://newtab");
    }
  }

  return pref;
}

SessionStartupPref GetStartupPref(const base::CommandLine& command_line, Profile* profile) {
  SessionStartupPref pref;

  if (!profile)
    return SessionStartupPref(SessionStartupPref::kLast);

  if (profile->IsGuestSession())
    return SessionStartupPref(SessionStartupPref::kLast);

  if (command_line.HasSwitch(switches::kRestoreLastSession))
    return SessionStartupPref(SessionStartupPref::kLast);

  if (profile->IsNewProfile()) {
#if defined(OS_CHROMEOS)
    pref.type = SessionStartupPref::kLast;
#else
    pref.type = SessionStartupPref::kLast;
#endif
  } else {
    pref.type = profile->GetPrefs()->GetInteger(prefs::kSessionStartupType);
  }

  if (profile->IsOffTheRecord())
    pref.type = SessionStartupPref::kLast;

  return pref;
}

SessionStartupPref GetStartupPref(const base::CommandLine& command_line, Profile* profile) {
  SessionStartupPref pref(SessionStartupPref::DEFAULT);
  if (!profile)
    return pref;

  // Handle first run or restart cases, logic for Chrome OS vs other platforms.
  // Also ensure new profiles and guest sessions are treated correctly.
  // Incognito sessions do not store session info, default to standard behavior.

  if (command_line.HasSwitch(switches::kRestoreLastSession))
    pref.type = SessionStartupPref::LAST;
  else if (command_line.HasSwitch(switches::kNewTab))
    pref.type = SessionStartupPref::NEW_TAB;
  else if (profile->IsNewProfile()) {
    pref.type = SessionStartupPref::DEFAULT;
  } else if (profile->IsGuestProfile()) {
    pref.type = SessionStartupPref::LAST;
  } else {
    pref = profile->GetPrefs()->GetEnumPrefValue(prefs::kSessionStartupPref,
        static_cast<int>(SessionStartupPref::LAST));
  }

  return pref;
}
